{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-E2bnBE/src/compare.js","content":"/**
 * Compares two strings by Unicode code point, ascending. Plain `<` on JS
 * strings compares UTF-16 code units, which disagrees with code point order
 * for characters outside the basic multilingual plane, so this walks both
 * strings as arrays of code points instead.
 */
export function compareByCodePoint(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const length = Math.min(left.length, right.length)
  for (let i = 0; i < length; i++) {
    const diff = left[i].codePointAt(0) - right[i].codePointAt(0)
    if (diff !== 0) return diff
  }
  return left.length - right.length
}
"}

