{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-E2bnBE/src/line-parser.js","content":"import { ParseError } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?\d(_?\d)*$/
const FLOAT = /^[+-]?\d(_?\d)*(\.\d(_?\d)*([eE][+-]?\d(_?\d)*)?|[eE][+-]?\d(_?\d)*)$/
const HEX4 = /^[0-9A-Fa-f]{4}$/
// A bare value token (a keyword, integer or float) runs until one of these
// characters, which can never be part of one; a `#`/`;` are deliberately not
// terminators here, so a comment marker glued onto a token stays part of its
// text and makes it invalid, per the spec's "runs into it" rule.
const BARE_STOP = /[ \t,\]}]/

/**
 * A cursor over a single line of the configuration document. Since every
 * directive fits on one line, all parsing - names, values, nested arrays and
 * inline tables - happens against one `LineParser` instance.
 */
export class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.pos = 0
    this.lineNo = lineNo
  }

  peek(offset = 0) {
    return this.line[this.pos + offset]
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  skipWs() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  /** True at end of line or at the start of a trailing comment. */
  atCommentOrEnd() {
    if (this.atEnd()) return true
    const c = this.peek()
    return c === '#' || c === ';'
  }

  /**
   * Skips whitespace, then treats a comment marker as running to the end of
   * the line (matching the spec's "ends the line" rule for `#`/`;` outside a
   * quoted string). Leaves `pos` at the line's length when a comment or the
   * real end was found, so callers can test `atEnd()` afterward.
   */
  skipWsAndComment() {
    this.skipWs()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) {
      this.pos = this.line.length
    }
  }

  /** Reads `name.name. ...`, with spaces/tabs allowed around each dot. */
  readDottedName() {
    const parts = []
    for (;;) {
      parts.push(this.readOneName())
      this.skipWs()
      if (this.peek() === '.') {
        this.pos++
        this.skipWs()
        continue
      }
      break
    }
    return parts
  }

  readOneName() {
    const c = this.peek()
    if (c === '"') return this.readBasicString()
    if (c === "'") return this.readLiteralString()
    const start = this.pos
    while (!this.atEnd() && NAME_CHAR.test(this.peek())) this.pos++
    if (this.pos === start) this.fail('expected a name')
    return this.line.slice(start, this.pos)
  }

  readBasicString() {
    this.pos++ // opening quote
    let result = ''
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.pos++
        return result
      }
      if (c === '\\') {
        this.pos++
        if (this.atEnd()) this.fail('unterminated string')
        const e = this.peek()
        if (e === '"') result += '"'
        else if (e === '\\') result += '\\'
        else if (e === 'n') result += '\n'
        else if (e === 't') result += '\t'
        else if (e === 'r') result += '\r'
        else if (e === '0') result += '\0'
        else if (e === 'u') {
          this.pos++
          const hex = this.line.slice(this.pos, this.pos + 4)
          if (hex.length < 4) this.fail('unterminated string')
          if (!HEX4.test(hex)) this.fail('invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          this.pos += 3 // one more below with the rest of the escapes
        } else {
          this.fail(`invalid escape \\${e}`)
        }
        this.pos++
      } else {
        result += c
        this.pos++
      }
    }
  }

  readLiteralString() {
    this.pos++ // opening quote
    const start = this.pos
    for (;;) {
      if (this.atEnd()) this.fail('unterminated string')
      if (this.peek() === "'") {
        const s = this.line.slice(start, this.pos)
        this.pos++
        return s
      }
      this.pos++
    }
  }

  /** Parses a value; `path` is the dotted path to it, used for errors and
   * key-redefinition checks raised by any inline table found within. */
  parseValue(path) {
    this.skipWs()
    if (this.atEnd()) this.fail('expected a value')
    const c = this.peek()
    if (c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { kind: 'string', value: this.readBasicString() }
    if (c === "'") return { kind: 'string', value: this.readLiteralString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    return this.parseBareValue()
  }

  parseBareValue() {
    const start = this.pos
    while (!this.atEnd() && !BARE_STOP.test(this.peek())) this.pos++
    const token = this.line.slice(start, this.pos)
    if (token === 'true') return { kind: 'boolean', value: true }
    if (token === 'false') return { kind: 'boolean', value: false }
    if (INTEGER.test(token)) return { kind: 'integer', text: normalizeInteger(token) }
    if (FLOAT.test(token)) return { kind: 'float', value: Number(token.replace(/_/g, '')) }
    this.fail(`invalid value ${token}`)
  }

  parseArray(path) {
    this.pos++ // '['
    const items = []
    for (;;) {
      this.skipWsAndComment()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.pos++
        break
      }
      items.push(this.parseValue(path))
      this.skipWsAndComment()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ',') {
        this.pos++
        this.skipWsAndComment()
        if (this.atEnd()) this.fail('unterminated array')
        if (this.peek() === ']') {
          this.pos++
          break
        }
        continue
      }
      if (this.peek() === ']') {
        this.pos++
        break
      }
      this.fail('unterminated array')
    }
    return { kind: 'array', items }
  }

  parseInlineTable(path) {
    this.pos++ // '{'
    const table = { kind: 'table', map: new Map(), headerDefined: true }
    this.skipWs()
    if (!this.atEnd() && this.peek() === '}') {
      this.pos++
      return table
    }
    for (;;) {
      if (this.atEnd() || this.peek() === '#' || this.peek() === ';') this.fail('unterminated inline table')
      const parts = this.readDottedName()
      this.skipWs()
      if (this.atEnd() || this.peek() !== '=') this.fail('expected = in an inline table')
      this.pos++
      this.skipWs()
      const value = this.parseValue(path.concat(parts))
      assignInto(this, table, parts, value, path)
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        this.skipWs()
        continue
      }
      if (c === '}') {
        this.pos++
        break
      }
      this.fail('unterminated inline table')
    }
    return table
  }
}

/** Strips underscores and normalizes sign/leading zeros so the result is a
 * valid, minimal JSON integer token (e.g. `-007` becomes `-7`, `+0` becomes `0`). */
function normalizeInteger(token) {
  let text = token.replace(/_/g, '')
  let sign = ''
  if (text[0] === '+') text = text.slice(1)
  else if (text[0] === '-') {
    sign = '-'
    text = text.slice(1)
  }
  text = text.replace(/^0+(?=\d)/, '')
  if (sign === '-' && text === '0') sign = ''
  return sign + text
}

/**
 * Walks `keyParts` through `table` from `pathPrefix`, creating intermediate
 * tables as needed and assigning `value` at the end. Shared by top-level
 * assignments and inline-table entries so both apply the same redefinition
 * and not-a-table rules.
 */
export function assignInto(p, table, keyParts, value, pathPrefix) {
  let cur = table
  const path = pathPrefix.slice()
  for (let i = 0; i < keyParts.length - 1; i++) {
    path.push(keyParts[i])
    cur = descendCreate(p, cur, keyParts[i], path.join('.'))
  }
  const last = keyParts[keyParts.length - 1]
  path.push(last)
  if (cur.map.has(last)) p.fail(`key ${path.join('.')} is defined twice`)
  cur.map.set(last, value)
}

/** Returns the table reached by walking through `key` on `cur`, creating a
 * fresh implicit table if it is absent, and using the last element when it
 * is an array of tables. */
export function descendCreate(p, cur, key, pathStr) {
  const existing = cur.map.get(key)
  if (existing === undefined) {
    const t = { kind: 'table', map: new Map(), headerDefined: false }
    cur.map.set(key, t)
    return t
  }
  if (existing.kind === 'table') return existing
  if (existing.kind === 'array-of-tables') return existing.items[existing.items.length - 1]
  p.fail(`${pathStr} is not a table`)
}
"}

