try {
  const root = parseDocument(input)
  const output = mode === 'json' ? formatJSON(root) : formatKeys(root)
  process.stdout.write(output)
  process.exit(0)
} catch (err) {
  if (err instanceof ParseError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}
"}

